INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20101, 'ឯកតានិមិត្ត \(i\) ត្រូវបានកំណត់ឱ្យមានលក្ខណៈមួយណា ?', NULL, '["\\(i^2=-1\\)", "\\(i^2=-i\\)", "\\(i^2=1\\)", "\\(i=-1\\)"]', 0, NULL, 1, 'mcq', 'ឯកតានិមិត្ត \(i\) ជាចំនួនដែលមានការ៉េស្មើ \(-1\) គឺ \(i^2=-1\)។', 'សញ្ញាណចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20102, 'ចំនួនកុំផ្លិចឆ្លាស់នៃ \(4 - 3i\) គឺ ៖', NULL, '["\\(-3 + 4i\\)", "\\(4 + 3i\\)", "\\(-4 + 3i\\)", "\\(-4 - 3i\\)"]', 1, NULL, 1, 'mcq', 'ចំនួនឆ្លាស់នៃ \(a+bi\) គឺ \(a-bi\) (ប្ដូរសញ្ញាផ្នែកនិមិត្តតែមួយ) ដូច្នេះ \(\bar z=4 + 3i\)។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20103, 'គណនា \((5+3i)+(-1+2i)\) ៖', NULL, '["\\(4 + i\\)", "\\(6 + 5i\\)", "\\(4 + 5i\\)", "\\(4 + 6i\\)"]', 2, NULL, 1, 'mcq', 'បូកផ្នែកពិតជាមួយផ្នែកពិត និងផ្នែកនិមិត្តជាមួយផ្នែកនិមិត្ត៖ \((5-1)+(3+2)i=4+5i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
