INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20104, 'ក្នុងប្លង់កុំផ្លិច ចំណុច \(M\) ជារូបភាពនៃចំនួនកុំផ្លិច \(z\) ដូចបង្ហាញក្នុងរូប។ \(z\) ស្មើ ៖', 'g12sc-cea84e081d.svg', '["\\(-3 + 2i\\)", "\\(3 + 2i\\)", "\\(2 + 3i\\)", "\\(3 - 2i\\)"]', 1, NULL, 1, 'mcq', 'ចំណុច \(M\) មានកូអរដោនេ \((3,\ 2)\) ដូច្នេះ \(z=3+2i\) (ផ្នែកពិតជាអាប់ស៊ីស ផ្នែកនិមិត្តជាអរដោនេ)។', 'ប្លង់កុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20105, 'ចំនួនកុំផ្លិច \(z=-2+3i\) មានផ្នែកពិត \(a\) និងផ្នែកនិមិត្ត \(b\) ស្មើ ៖', NULL, '["\\(a=2,\\ b=3\\)", "\\(a=-2,\\ b=3i\\)", "\\(a=3,\\ b=-2\\)", "\\(a=-2,\\ b=3\\)"]', 3, NULL, 1, 'mcq', 'ក្នុងទម្រង់ \(a+bi\) ផ្នែកពិតគឺ \(a=-2\) ហើយផ្នែកនិមិត្តគឺ \(b=3\) (មេគុណនៃ \(i\) មិនមែន \(3i\))។', 'សញ្ញាណចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20106, 'គណនា \((9-2i)-(4-4i)\) ៖', NULL, '["\\(13 - 6i\\)", "\\(5 - 6i\\)", "\\(5 + 2i\\)", "\\(5 + 6i\\)"]', 2, NULL, 1, 'mcq', '\((9-4)+[-2-(-4)]i=5+2i\) (ប្រយ័ត្នសញ្ញាពេលដកផ្នែកនិមិត្តអវិជ្ជមាន)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
