INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20107, 'ក្នុងរូប ចំណុច \(A\) ជារូបភាពនៃចំនួនកុំផ្លិច \(z\)។ ចំណុចរូបភាពនៃ \(\bar z\) មានកូអរដោនេ ៖', 'g12sc-54053a7c13.svg', '["\\((2,\\ -3)\\)", "\\((3,\\ 2)\\)", "\\((-2,\\ -3)\\)", "\\((-2,\\ 3)\\)"]', 0, NULL, 1, 'mcq', '\(z=2+3i\) ដូច្នេះ \(\bar z=2-3i\) មានរូបភាព \((2,\ -3)\) ជាចំណុចឆ្លុះនៃ \(A\) ធៀបនឹងអ័ក្សពិត។', 'ប្លង់កុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20108, 'ចំនួនកុំផ្លិចផ្ទុយនៃ \(-3 - i\) គឺ ៖', NULL, '["\\(-3 + i\\)", "\\(3 + i\\)", "\\(-3 - i\\)", "\\(3 - i\\)"]', 1, NULL, 1, 'mcq', 'ចំនួនផ្ទុយនៃ \(a+bi\) គឺ \(-a-bi\) (ប្ដូរសញ្ញាទាំងផ្នែកពិត និងផ្នែកនិមិត្ត) ដូច្នេះ \(-z=3 + i\)។', 'សញ្ញាណចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20109, 'ផលគុណ \((a+bi)(c+di)\) ស្មើ ៖', NULL, '["\\((ac-bd)+(ad-bc)i\\)", "\\((ac+bd)+(ad-bc)i\\)", "\\(ac+bdi\\)", "\\((ac-bd)+(ad+bc)i\\)"]', 3, NULL, 1, 'mcq', 'ពន្លាតរួចប្រើ \(i^2=-1\) ៖ \(ac+adi+bci+bdi^2=(ac-bd)+(ad+bc)i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20110, 'ក្នុងចំណោមចំនួនខាងក្រោម តើចំនួនមួយណាជា «ចំនួននិមិត្ត» (ផលគុណនៃចំនួនពិតមិនសូន្យនិង \(i\)) ?', NULL, '["\\(7i\\)", "\\(7\\)", "\\(i^2\\)", "\\(7+i\\)"]', 0, NULL, 1, 'mcq', '\(7i=0+7i\) មានផ្នែកពិតស្មើ \(0\) ហើយផ្នែកនិមិត្តមិនសូន្យ។ \(i^2=-1\) ជាចំនួនពិត ឯ \(7+i\) មានផ្នែកពិតមិនសូន្យ។', 'សញ្ញាណចំនួនកុំផ្លិច', 'easy', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20111, 'គណនា \((2+3i)(4+2i)\) ៖', NULL, '["\\(14 + 16i\\)", "\\(2 + 16i\\)", "\\(8 + 6i\\)", "\\(2 + 8i\\)"]', 1, NULL, 2, 'mcq', '\((2+3i)(4+2i)=8+4i+12i+6i^2=8+16i-6=2+16i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20112, 'គេមានសមីការ \(3x-\sqrt{-25}=-6+3yi\) ដែល \(x,\ y\) ជាចំនួនពិត។ តម្លៃ \(x\) និង \(y\) គឺ ៖', NULL, '["\\(x=-2,\\ y=\\dfrac{5}{3}\\)", "\\(x=-6,\\ y=-5\\)", "\\(x=-2,\\ y=-\\dfrac{5}{3}\\)", "\\(x=2,\\ y=-\\dfrac{5}{3}\\)"]', 2, NULL, 2, 'mcq', '\(\sqrt{-25}=5i\) ដូច្នេះ \(3x-5i=-6+3yi\)។ ផ្ទឹមផ្នែកពិត \(3x=-6\) និងផ្នែកនិមិត្ត \(-5=3y\) បាន \(x=-2,\ y=-\dfrac53\)។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
