INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20113, 'ក្នុងរូប \(M_1\) និង \(M_2\) ជារូបភាពនៃ \(z_1\) និង \(z_2\) រៀងគ្នា។ រូបភាពនៃ \(z_1+z_2\) មានកូអរដោនេ ៖', 'g12sc-dc39fac454.svg', '["\\((2,\\ 3)\\)", "\\((4,\\ -1)\\)", "\\((3,\\ 2)\\)", "\\((-3,\\ 2)\\)"]', 0, NULL, 2, 'mcq', 'អានពីរូប \(z_1=3+i\) និង \(z_2=-1+2i\)។ \(z_1+z_2=(3-1)+(1+2)i=2+3i\) ដូច្នេះរូបភាពគឺ \((2,\ 3)\) ជាចុងអង្កត់ទ្រូងនៃប្រលេឡូក្រាមដែលមានជ្រុង \(OM_1\) និង \(OM_2\)។', 'ប្លង់កុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20114, 'គណនា \(3i(5-4i)\) ៖', NULL, '["\\(12 - 15i\\)", "\\(15 - 12i\\)", "\\(-12 + 15i\\)", "\\(12 + 15i\\)"]', 3, NULL, 2, 'mcq', '\(3i(5-4i)=15i-12i^2=15i+12=12+15i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20115, 'ចំពោះគ្រប់ចំនួនកុំផ្លិច \(z_1,\ z_2\) តើសមភាពមួយណាត្រឹមត្រូវជានិច្ច ?', NULL, '["\\(\\overline{z_1+z_2}=\\overline{z_1}-\\overline{z_2}\\)", "\\(\\overline{z_1z_2}=\\overline{z_1}+\\overline{z_2}\\)", "\\(\\overline{z_1z_2}=\\overline{z_1}\\cdot\\overline{z_2}\\)", "\\(\\overline{z_1z_2}=-\\overline{z_1}\\cdot\\overline{z_2}\\)"]', 2, NULL, 2, 'mcq', 'ចំនួនឆ្លាស់នៃផលគុណ ស្មើផលគុណនៃចំនួនឆ្លាស់។ ឧទាហរណ៍ \(z_1=5-i,\ z_2=2+3i\) ៖ \(z_1z_2=13+13i\) ចំនួនឆ្លាស់ \(13-13i=(5+i)(2-3i)\)។ សមភាពផ្សេងទៀតមិនពិតជានិច្ចទេ (ឧ. \(\overline{z_1+z_2}=\overline{z_1}+\overline{z_2}\))។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20116, 'គេឱ្យ \(z_1=2+i\) និង \(z_2=1+2i\)។ រូបភាពនៃ \(z_1-z_2\) មានកូអរដោនេ ៖', NULL, '["\\((-1,\\ 1)\\)", "\\((1,\\ 1)\\)", "\\((1,\\ -1)\\)", "\\((3,\\ 3)\\)"]', 2, NULL, 2, 'mcq', '\(z_1-z_2=(2-1)+(1-2)i=1-i\) ដូច្នេះរូបភាពគឺ \((1,\ -1)\)។ (បើជាចំនួនបញ្ច្រាស់ \(z_2-z_1\) នឹងបានចំណុចឆ្លុះតាមគល់ \(O\))។', 'ប្លង់កុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20117, 'គណនា \(\dfrac{3}{2+i}\) រួចសរសេរជាទម្រង់ \(a+bi\) ៖', NULL, '["\\(\\dfrac{3}{5} - \\dfrac{6}{5}i\\)", "\\(\\dfrac{6}{5} - \\dfrac{3}{5}i\\)", "\\(2 - i\\)", "\\(\\dfrac{6}{5} + \\dfrac{3}{5}i\\)"]', 1, NULL, 2, 'mcq', 'គុណភាគយក និងភាគបែងនឹងចំនួនឆ្លាស់នៃភាគបែង ៖ \(\dfrac{3(2-i)}{(2+i)(2-i)}=\dfrac{6-3i}{5}=\dfrac65-\dfrac35i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20118, 'ផលបូក \((3+4i)+(3-4i)\) ជាចំនួនប្រភេទអ្វី ហើយស្មើប៉ុន្មាន ?', NULL, '["ចំនួននិមិត្តសុទ្ធ \\(8i\\)", "ចំនួនកុំផ្លិច \\(6+8i\\)", "ចំនួនពិត \\(6\\)", "ចំនួនពិត \\(0\\)"]', 2, NULL, 2, 'mcq', 'ចំនួនឆ្លាស់បូកគ្នាផ្នែកនិមិត្តលុបគ្នា ៖ \(z+\bar z=2a\) ជាចំនួនពិតជានិច្ច។ ក្នុងករណីនេះ \(=6\)។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20119, 'គណនា \(\dfrac{3+2i}{1-3i}\) ៖', NULL, '["\\(- \\dfrac{3}{10} - \\dfrac{11}{10}i\\)", "\\(- \\dfrac{3}{10} + \\dfrac{11}{10}i\\)", "\\(\\dfrac{9}{10} - \\dfrac{7}{10}i\\)", "\\(\\dfrac{3}{10} + \\dfrac{11}{10}i\\)"]', 1, NULL, 2, 'mcq', '\(\dfrac{(3+2i)(1+3i)}{(1-3i)(1+3i)}=\dfrac{3+9i+2i-6}{10}=\dfrac{-3+11i}{10}\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20120, 'គណនា \((2-i)^2\) ៖', NULL, '["\\(3 - 4i\\)", "\\(3 + 4i\\)", "\\(3 - 2i\\)", "\\(5 - 4i\\)"]', 0, NULL, 2, 'mcq', '\((2-i)^2=4-4i+i^2=4-4i-1=3-4i\) (ប្រយ័ត្ន \(i^2=-1\) មិនមែន \(1\))។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20121, 'គេឱ្យ \(z_1=3+2i\) និង \(z_2=1-7i\)។ ផលគុណ \(z_1z_2\) ស្មើ ៖', NULL, '["\\(-11 - 19i\\)", "\\(3 - 14i\\)", "\\(17 - 23i\\)", "\\(17 - 19i\\)"]', 3, NULL, 2, 'mcq', '\(z_1z_2=(3\cdot1-2\cdot(-7))+(3\cdot(-7)+2\cdot1)i=17-19i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20122, 'សិស្សម្នាក់គណនា \((2+i)(2-i)=4-i^2=4-1=3\)។ តើកំហុសរបស់សិស្សនេះនៅត្រង់ណា ហើយចម្លើយត្រឹមត្រូវគឺប៉ុន្មាន ?', NULL, '["ត្រូវប្រើ \\(i^2=1\\) ដូច្នេះចម្លើយគឺ \\(3\\)", "ពន្លាតខុស ព្រោះ \\((2+i)(2-i)=4+i^2\\) ដូច្នេះចម្លើយគឺ \\(3\\)", "គ្មានកំហុសទេ ព្រោះ \\((2+i)(2-i)=3\\) ត្រឹមត្រូវ", "ចាត់ទុក \\(-i^2=-1\\) ខុស ព្រោះ \\(-i^2=+1\\) ដូច្នេះចម្លើយគឺ \\(5\\)"]', 3, NULL, 2, 'mcq', '\((a+b)(a-b)=a^2-b^2\) ដូច្នេះ \((2+i)(2-i)=2^2-i^2\)។ ដោយ \(i^2=-1\) គេបាន \(4-(-1)=5\)។ សិស្សបានប្ដូរសញ្ញាខុសត្រង់ \(-i^2\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20123, 'គណនា \(\dfrac{1+i}{1-i}\) ៖', NULL, '["\\(-i\\)", "\\(1\\)", "\\(2i\\)", "\\(i\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{(1+i)(1+i)}{(1-i)(1+i)}=\dfrac{1+2i+i^2}{2}=\dfrac{2i}{2}=i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20124, 'គណនា \(\dfrac{1}{1+i}\) ៖', NULL, '["\\(\\dfrac{1}{2} - \\dfrac{1}{2}i\\)", "\\(-1 - i\\)", "\\(\\dfrac{1}{2} + \\dfrac{1}{2}i\\)", "\\(1 - i\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{1}{1+i}=\dfrac{1-i}{(1+i)(1-i)}=\dfrac{1-i}{2}=\dfrac12-\dfrac12i\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20125, 'គេឱ្យ \(z=\dfrac{i-x}{i+x}\) ដែល \(x\) ជាចំនួនពិត។ ផលគុណ \(z\cdot\bar z\) ស្មើ ៖', NULL, '["\\(-1\\)", "\\(\\dfrac{1-x^2}{1+x^2}\\)", "\\(1\\)", "\\(x^2+1\\)"]', 2, NULL, 3, 'mcq', '\(\bar z=\dfrac{-i-x}{-i+x}\) ដូច្នេះ \(z\bar z=\dfrac{(i-x)(-i-x)}{(i+x)(x-i)}=\dfrac{x^2+1}{x^2+1}=1\) (ព្រោះ \((i-x)(-i-x)=-i^2-ix+ix+x^2=1+x^2\) និង \((i+x)(x-i)=x^2-i^2=x^2+1\))។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-504c1aa930.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20126, 'ក្នុងរូប ចំណុច \(P\) ជារូបភាពនៃ \(z=2+3i\)។ តើឃ្លាមួយណាត្រឹមត្រូវ ?', 'g12sc-504c1aa930.svg', '["\\(Q\\) ជារូបភាពនៃ \\(\\bar z\\) ហើយ \\(R\\) ជារូបភាពនៃ \\(-z\\)", "\\(S\\) ជារូបភាពនៃ \\(\\bar z\\) ហើយ \\(Q\\) ជារូបភាពនៃ \\(-z\\)", "\\(Q\\) ជារូបភាពនៃ \\(-z\\) ហើយ \\(S\\) ជារូបភាពនៃ \\(\\bar z\\)", "\\(R\\) ជារូបភាពនៃ \\(\\bar z\\) ហើយ \\(S\\) ជារូបភាពនៃ \\(-z\\)"]', 0, NULL, 3, 'mcq', '\(\bar z=2-3i\) មានរូបភាព \((2,-3)=Q\) (ឆ្លុះតាមអ័ក្សពិត)។ \(-z=-2-3i\) មានរូបភាព \((-2,-3)=R\) (ឆ្លុះតាមគល់ \(O\))។ \(S(-2,3)\) ជារូបភាពនៃ \(-\bar z\)។', 'ប្លង់កុំផ្លិច', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20127, 'គេដឹងថា \(z+\bar z=6\) និង \(z\cdot\bar z=13\)។ សមីការដឺក្រេទី ២ មានមេគុណពិត ដែលមាន \(z\) ជាឫស គឺ ៖', NULL, '["\\(Z^2-13Z+6=0\\)", "\\(Z^2-6Z-13=0\\)", "\\(Z^2+6Z+13=0\\)", "\\(Z^2-6Z+13=0\\)"]', 3, NULL, 3, 'mcq', 'ឫសទាំងពីរគឺ \(z\) និង \(\bar z\) ដែលមានផលបូក \(6\) និងផលគុណ \(13\)។ សមីការគឺ \(Z^2-(\text{ផលបូក})Z+(\text{ផលគុណ})=0\) ឬ \(Z^2-6Z+13=0\) (ឫស \(3\pm2i\))។', 'សញ្ញាណចំនួនកុំផ្លិច', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20128, 'ចំពោះចំនួនកុំផ្លិច \(z=a+bi\) ដែល \(a,\ b\) ជាចំនួនពិត តើឃ្លាមួយណាពិត ?', NULL, '["\\(z-\\bar z\\) ជាចំនួនពិតជានិច្ច", "\\(z\\cdot\\bar z\\) ជាចំនួនពិតមិនអវិជ្ជមានជានិច្ច", "\\(\\dfrac{z}{\\bar z}\\) ជាចំនួនពិតជានិច្ច", "\\(z+\\bar z\\) ជាចំនួននិមិត្តសុទ្ធជានិច្ច"]', 1, NULL, 3, 'mcq', '\(z\bar z=a^2+b^2\ge0\) ពិត។ \(z-\bar z=2bi\) មិនមែនចំនួនពិតបើ \(b\ne0\)។ \(z+\bar z=2a\) ជាចំនួនពិត (មិនមែននិមិត្តសុទ្ធ)។ ឧទាហរណ៍ \(z=i\) ។ ឧទាហរណ៍ \(z=1+i\) ឱ្យ \(\dfrac{z}{\bar z}=\dfrac{1+i}{1-i}=i\) មិនមែនជាចំនួនពិត។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20129, 'កំណត់តម្លៃពិត \(x\) ដើម្បីឱ្យ \(\dfrac{3+i}{1+i}+\dfrac{x-i}{1-i}\) ជាចំនួនពិត ៖', NULL, '["\\(x=2\\)", "\\(x=-3\\)", "\\(x=3\\)", "\\(x=1\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{3+i}{1+i}=2-i\) និង \(\dfrac{x-i}{1-i}=\dfrac{x+1}{2}+\dfrac{x-1}{2}i\)។ ផលបូកមានផ្នែកនិមិត្ត \(\dfrac{x-3}{2}\) ត្រូវស្មើសូន្យ ដូច្នេះ \(x=3\)។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20130, 'រកចំនួនកុំផ្លិច \(z\) ដែលផ្ទៀងផ្ទាត់ \(z+2\bar z=3+2i\) ៖', NULL, '["\\(1 - 2i\\)", "\\(-1 + 2i\\)", "\\(1 + 2i\\)", "\\(3 - 2i\\)"]', 0, NULL, 3, 'mcq', 'តាង \(z=a+bi\) \(z+2\bar z=3a-bi\)។ ផ្ទឹម \(3a-bi=3+2i\) បាន \(a=1\) និង \(b=-2\) ដូច្នេះ \(z=1-2i\)។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20131, 'បើ \(z\) ជាចំនួនកុំផ្លិច ហើយ \(z^2\) ជាចំនួនពិតអវិជ្ជមាន (\(z^2<0\)) នោះ \(z\) ត្រូវតែជា ៖', NULL, '["ចំនួនកុំផ្លិចមិនសូន្យណាក៏បាន \\(z\\ne0\\)", "ចំនួននិមិត្តសុទ្ធ \\(z=bi\\) ដែល \\(b\\ne0\\)", "ចំនួនពិតវិជ្ជមាន \\(z=a\\) ដែល \\(a>0\\)", "ចំនួនពិតអវិជ្ជមាន \\(z=-a\\) ដែល \\(a>0\\)"]', 1, NULL, 3, 'mcq', '\(z=a+bi\) \(z^2=(a^2-b^2)+2abi\) ជាចំនួនពិតអវិជ្ជមាន ត្រូវការ \(2ab=0\) ហើយ \(a^2-b^2<0\)។ បើ \(b=0\) នោះ \(z^2=a^2\ge0\) (ផ្ទុយ) ដូច្នេះ \(a=0\) ហើយ \(b\ne0\)។', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'hard', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-e0eb9e3ae8.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20132, 'ក្នុងការប្រកួតដ្រូន ទីតាំងដ្រូន \(A\) និង \(B\) ត្រូវបានកត់ត្រាជាចំនួនកុំផ្លិច (១ ឯកតា = ១ km ; ផ្នែកពិតជាចម្ងាយទៅខាងកើត ផ្នែកនិមិត្តជាចម្ងាយទៅខាងជើង) ដូចក្នុងរូប។ ដើម្បីហោះពី \(A\) ទៅ \(B\) ដ្រូន \(A\) ត្រូវធ្វើបម្លាស់ទីតាមចំនួនកុំផ្លិច ៖', 'g12sc-e0eb9e3ae8.svg', '["\\(-3 + 4i\\)", "\\(5 + 10i\\)", "\\(3 - 4i\\)", "\\(3 + 4i\\)"]', 0, NULL, 3, 'mcq', 'បម្លាស់ទីពី \(A\) ទៅ \(B\) ស្មើ \(z_B-z_A=(1+7i)-(4+3i)=-3+4i\) (ទៅខាងលិច \(3\) km ហើយទៅខាងជើង \(4\) km)។ \(z_A-z_B\) ជាបម្លាស់ទីបញ្ច្រាស់។', 'ប្លង់កុំផ្លិច', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20133, 'ក្នុងសៀគ្វីអគ្គិសនីចរន្តឆ្លាស់ ភាពទប់ (impedance) តាងដោយចំនួនកុំផ្លិច \(Z=R+Xi\) (គិតជា Ω) ដែល \(R\) ជាភាពទប់ធន់ និង \(X\) ជាភាពទប់ប្រតិកម្ម។ សៀគ្វីពីរដែលមាន \(Z_1=3+4i\) និង \(Z_2=1-2i\) ត្រូវបានភ្ជាប់ជាស៊េរី។ ភាពទប់សរុបគឺ ៖', NULL, '["\\(4 - 2i\\ \\Omega\\)", "\\(4 + 6i\\ \\Omega\\)", "\\(2 + 6i\\ \\Omega\\)", "\\(4 + 2i\\ \\Omega\\)"]', 3, NULL, 3, 'mcq', 'ក្នុងសៀគ្វីស៊េរី ភាពទប់សរុបស្មើផលបូក ៖ \(Z=Z_1+Z_2=(3+1)+(4-2)i=4+2i\ \Omega\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-ad39e765c9.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20134, 'សាលា \(A\) និងសាលា \(B\) មានទីតាំងតាមចំនួនកុំផ្លិច \(-2+6i\) និង \(4-2i\) (១ ឯកតា = ១ km) ដូចក្នុងរូប។ គណៈកម្មការចង់រៀបកិច្ចប្រជុំត្រង់ចំណុចកណ្ដាលនៃផ្លូវត្រង់រវាងសាលាទាំងពីរ។ ចំណុចប្រជុំត្រូវមានទីតាំង ៖', 'g12sc-ad39e765c9.svg', '["\\(2 + 4i\\)", "\\(1 + 2i\\)", "\\(1 + 4i\\)", "\\(6 - 8i\\)"]', 1, NULL, 3, 'mcq', 'ចំណុចកណ្ដាលស្មើមធ្យមនព្វន្តនៃចំនួនកុំផ្លិចទាំងពីរ ៖ \(\dfrac{z_A+z_B}{2}=\dfrac{(-2+6i)+(4-2i)}{2}=\dfrac{2+4i}{2}=1+2i\)។', 'ប្លង់កុំផ្លិច', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-34d512635b.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20135, 'មនុស្សយន្តមួយចាប់ផ្ដើមពីទីតាំង \(S=1+4i\) ហើយរៀងរាល់ជំហានវាធ្វើបម្លាស់ទី \(v=2-i\) ដូចក្នុងរូប (ជំហានទី ១)។ តើក្រោយពីធ្វើបម្លាស់ទីប៉ុន្មានជំហាន ទើបមនុស្សយន្តមកដល់អ័ក្សពិត ?', 'g12sc-34d512635b.svg', '["5 ជំហាន", "2 ជំហាន", "3 ជំហាន", "4 ជំហាន"]', 3, NULL, 3, 'mcq', 'ក្រោយ \(n\) ជំហាន ទីតាំងគឺ \(S+nv=(1+2n)+(4-n)i\)។ នៅលើអ័ក្សពិតផ្នែកនិមិត្តស្មើសូន្យ \(4-n=0\) បាន \(n=4\) ហើយទីតាំងគឺ \(9\)។', 'ប្លង់កុំផ្លិច', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20136, 'តាមច្បាប់អូម \(V=I\cdot Z\) ដែលចរន្ត \(I=2-i\) (A) ហូរកាត់ភាពទប់ \(Z=3+2i\) (Ω)។ វ៉ុលតាព \(V\) ស្មើ ៖', NULL, '["\\(6 - 2i\\ \\text{V}\\)", "\\(4 + i\\ \\text{V}\\)", "\\(8 + i\\ \\text{V}\\)", "\\(8 - i\\ \\text{V}\\)"]', 2, NULL, 3, 'mcq', '\(V=(2-i)(3+2i)=6+4i-3i-2i^2=6+i+2=8+i\ \text{V}\)។', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'pisa', 1, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20137, 'គេឱ្យ \(z_1=1+2i\) និង \(z_2=3-5i\)។ គណនា \(z_1+z_2\) និង \(z_1z_2\) ដោយសរសេរជាទម្រង់ \(a+bi\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ផលបូក ៖ \(z_1+z_2=(1+3)+(2-5)i=4 - 3i\) (1 ពិន្ទុ)
ពន្លាតផលគុណ ៖ \(z_1z_2=(1+2i)(3-5i)=3-5i+6i-10i^2\) (2 ពិន្ទុ)
ជំនួស \(i^2=-1\) ហើយប្រមូលតួ ៖ \(=3+i+10=13 + i\) (2 ពិន្ទុ)', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'easy', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20138, 'សរសេរចំនួនកុំផ្លិច \(z=\dfrac{1+3i}{2-i}-\dfrac{2+i}{1+2i}\) ជាទម្រង់ពីជគណិត \(a+bi\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាគយក និងភាគបែងនៃប្រភាគទី ១ គុណនឹង \(2+i\) ៖ \(\dfrac{(1+3i)(2+i)}{5}=\dfrac{-1 + 7i}{5}\) (1 ពិន្ទុ)
ប្រភាគទី ២ គុណនឹង \(1-2i\) ៖ \(\dfrac{(2+i)(1-2i)}{5}=\dfrac{4 - 3i}{5}\) (1 ពិន្ទុ)
ដកគ្នា ៖ \(z=\dfrac{(-1+7i)-(4-3i)}{5}\) (1 ពិន្ទុ)
សម្រួល ៖ \(z=\dfrac{-5+10i}{5}\) (1 ពិន្ទុ)
ចម្លើយ ៖ \(z=-1 + 2i\) (1 ពិន្ទុ)', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20139, 'រកចំនួនពិត \(x\) និង \(y\) ដែល \((x+iy)(2-i)=5+5i\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាត ៖ \((x+iy)(2-i)=2x-xi+2yi-yi^2=(2x+y)+(2y-x)i\) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកពិត ៖ \(2x+y=5\) (1) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកនិមិត្ត ៖ \(-x+2y=5\) (2) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធ ៖ \((1)+2\times(2)\) បាន \(5y=15\) ដូច្នេះ \(y=3\) ហើយ \(x=1\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \((1+3i)(2-i)=2-i+6i-3i^2=5+5i\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
