INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20140, 'ក្នុងប្លង់កុំផ្លិច ចំណុច \(M_1\) និង \(M_2\) ជារូបភាពនៃ \(z_1\) និង \(z_2\) ដូចក្នុងរូប។ ក. សរសេរ \(z_1\) និង \(z_2\) តាមរូប។ ខ. គណនា \(z_1+z_2\) និង \(z_1-z_2\)។ គ. ពន្យល់ពីរបៀបសង់រូបភាពនៃ \(z_1+z_2\) ដោយធរណីមាត្រ។', 'g12sc-70154227fb.svg', '[]', 0, NULL, 5, 'writing', 'អានកូអរដោនេ ៖ \(M_1(3,\ 1)\) ដូច្នេះ \(z_1=3+i\) (1 ពិន្ទុ)
\(M_2(-1,\ 2)\) ដូច្នេះ \(z_2=-1+2i\) (1 ពិន្ទុ)
ផលបូក ៖ \(z_1+z_2=(3-1)+(1+2)i=2+3i\) (1 ពិន្ទុ)
ផលដក ៖ \(z_1-z_2=(3+1)+(1-2)i=4-i\) (1 ពិន្ទុ)
ធរណីមាត្រ ៖ \(\overrightarrow{OM}=\overrightarrow{OM_1}+\overrightarrow{OM_2}\) ជាអង្កត់ទ្រូងនៃប្រលេឡូក្រាមដែលមានជ្រុង \(OM_1\) និង \(OM_2\) ចំណុច \(M(2,\ 3)\)។ (1 ពិន្ទុ)', 'ប្លង់កុំផ្លិច', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20141, 'ក. ស្រាយបញ្ជាក់ថា ចំពោះគ្រប់ \(z=a+bi\) (\(a,\ b\) ជាចំនួនពិត) ផលគុណ \(z\cdot\bar z\) ជាចំនួនពិតមិនអវិជ្ជមាន។ ខ. ផ្ទៀងផ្ទាត់ជាមួយ \(z=3-4i\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរ \(\bar z=a-bi\) ហើយពន្លាត \(z\bar z=(a+bi)(a-bi)=a^2-abi+abi-b^2i^2\) (1 ពិន្ទុ)
ប្រើ \(i^2=-1\) ៖ \(z\bar z=a^2+b^2\) (1 ពិន្ទុ)
ដោយ \(a^2\ge0\) និង \(b^2\ge0\) នោះ \(a^2+b^2\ge0\) ជាចំនួនពិតមិនអវិជ្ជមាន (1 ពិន្ទុ)
ករណីស្មើសូន្យ ៖ \(z\bar z=0\) លុះត្រាតែ \(a=b=0\) គឺ \(z=0\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \((3-4i)(3+4i)=9+16=25=3^2+(-4)^2\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'medium', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20142, 'គេឱ្យ \(z=\dfrac{i-x}{i+x}\) ដែល \(x\) ជាចំនួនពិត។ ក. បង្ហាញថា \(z\cdot\bar z=1\)។ ខ. សរសេរ \(z\) ជាទម្រង់ \(a+bi\)។ គ. រកតម្លៃ \(x\) ដើម្បីឱ្យ \(z=i\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ចំនួនឆ្លាស់ ៖ \(\bar z=\dfrac{-i-x}{-i+x}\) ដូច្នេះ \(z\bar z=\dfrac{(i-x)(-i-x)}{(i+x)(x-i)}\) (1 ពិន្ទុ)
គណនា ៖ \((i-x)(-i-x)=1+x^2\) និង \((i+x)(x-i)=x^2+1\) នាំឱ្យ \(z\bar z=1\) (1 ពិន្ទុ)
គុណភាគយក និងភាគបែងនឹង \(x-i\) ៖ \(z=\dfrac{(i-x)(x-i)}{(x+i)(x-i)}=\dfrac{1-x^2+2xi}{x^2+1}\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(z=\dfrac{1-x^2}{1+x^2}+\dfrac{2x}{1+x^2}i\) (1 ពិន្ទុ)
ដើម្បីឱ្យ \(z=i\) ត្រូវការ \(1-x^2=0\) និង \(\dfrac{2x}{1+x^2}=1\)។ សមីការទី ២ ឱ្យ \((x-1)^2=0\) ដូច្នេះ \(x=1\) (ផ្ទៀងផ្ទាត់ \(\dfrac{i-1}{i+1}=i\))។ (1 ពិន្ទុ)', 'ចំនួនកុំផ្លិចឆ្លាស់និងសមភាព', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20143, 'ក. សរសេរសមីការដឺក្រេទី ២ ជាទម្រង់ \(Z^2+pZ+q=0\) ដែល \(p,\ q\) ជាចំនួនពិត ហើយមាន \(2+3i\) ជាឫសមួយ។ ខ. ផ្ទៀងផ្ទាត់ថា \(2+3i\) ពិតជាឫសនៃសមីការនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'សមីការមានមេគុណពិត ដូច្នេះឫសមួយទៀតគឺចំនួនឆ្លាស់ \(2-3i\) (1 ពិន្ទុ)
ផលបូកឫស ៖ \((2+3i)+(2-3i)=4\) (1 ពិន្ទុ)
ផលគុណឫស ៖ \((2+3i)(2-3i)=4+9=13\) (1 ពិន្ទុ)
សមីការ ៖ \(Z^2-4Z+13=0\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \((2+3i)^2-4(2+3i)+13=(-5+12i)-8-12i+13=0\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'សញ្ញាណចំនួនកុំផ្លិច', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20144, 'ដោះស្រាយប្រព័ន្ធសមីការ \(\begin{cases} z_1+2z_2=4+3i \\ 2z_1-z_2=3-4i \end{cases}\) ដែលមិនស្គាល់ជាចំនួនកុំផ្លិច \(z_1\) និង \(z_2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កម្ចាត់ \(z_2\) ៖ គុណសមីការទី ២ នឹង \(2\) បាន \(4z_1-2z_2=6-8i\) (1 ពិន្ទុ)
បូកនឹងសមីការទី ១ ៖ \(5z_1=10-5i\) (1 ពិន្ទុ)
ដូច្នេះ \(z_1=2-i\) (1 ពិន្ទុ)
ជំនួសក្នុងសមីការទី ១ ៖ \(2z_2=4+3i-(2-i)=2+4i\) ដូច្នេះ \(z_2=1+2i\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់សមីការទី ២ ៖ \(2(2-i)-(1+2i)=4-2i-1-2i=3-4i\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20145, 'សិស្សម្នាក់សរសេរថា \(\dfrac{a+bi}{c+di}=\dfrac{a}{c}+\dfrac{b}{d}i\)។ ក. បង្ហាញថាវិធីនេះខុស ដោយប្រើ \(\dfrac{1+i}{1-i}\)។ ខ. ចូរបង្ហាញរូបមន្តត្រឹមត្រូវ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាមវិធីរបស់សិស្ស ៖ \(\dfrac{1+i}{1-i}=\dfrac11+\dfrac{1}{-1}i=1-i\) (1 ពិន្ទុ)
តាមការគណនាត្រឹមត្រូវ ៖ \(\dfrac{(1+i)(1+i)}{(1-i)(1+i)}=\dfrac{2i}{2}=i\) (1 ពិន្ទុ)
ដោយ \(1-i\ne i\) វិធីរបស់សិស្សខុស (ក្នុងចំនួនកុំផ្លិច មិនអាចចែកផ្នែកពិត និងផ្នែកនិមិត្តដាច់ដោយឡែកបានទេ) (1 ពិន្ទុ)
រូបមន្តត្រឹមត្រូវ ៖ គុណនឹង \(c-di\) បាន \(\dfrac{(a+bi)(c-di)}{(c+di)(c-di)}=\dfrac{(ac+bd)+(bc-ad)i}{c^2+d^2}\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(a=b=c=1,\ d=-1\) ឱ្យ \(\dfrac{(1-1)+(1+1)i}{2}=i\) ស្របនឹងចម្លើយត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'hard', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20146, 'សៀគ្វីអគ្គិសនីចរន្តឆ្លាស់មានផ្នែកពីរភ្ជាប់ស៊េរី ដែលមានភាពទប់ \(Z_1=3+4i\ \Omega\) និង \(Z_2=1-2i\ \Omega\)។ វ៉ុលតាពចូលគឺ \(V=20+10i\ \text{V}\)។ ក. គណនាភាពទប់សរុប \(Z\)។ ខ. គណនាចរន្ត \(I=\dfrac{V}{Z}\) ហើយពន្យល់ថាហេតុអ្វីបានជាលទ្ធផលជាចំនួនពិត។ គ. ផ្ទៀងផ្ទាត់ \(V=I\cdot Z\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាពទប់សរុប ៖ \(Z=Z_1+Z_2=4+2i\ \Omega\) (1 ពិន្ទុ)
ចរន្ត ៖ \(I=\dfrac{20+10i}{4+2i}\) គុណភាគយក និងភាគបែងនឹង \(4-2i\) (1 ពិន្ទុ)
ភាគយក ៖ \((20+10i)(4-2i)=80-40i+40i-20i^2=100\) ហើយភាគបែង \((4+2i)(4-2i)=16+4=20\) (1 ពិន្ទុ)
ដូច្នេះ \(I=\dfrac{100}{20}=5\ \text{A}\)។ ជាចំនួនពិត ព្រោះ \(V=20+10i=5(4+2i)=5Z\) គឺ \(V\) ជាពហុគុណពិតនៃ \(Z\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(I\cdot Z=5(4+2i)=20+10i=V\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
