INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20147, 'កម្លាំងពីរ \(F_1\) និង \(F_2\) សកម្មលើចំណុចមួយ ត្រូវបានតាងដោយចំនួនកុំផ្លិច (គិតជា kN) ដូចក្នុងរូប។ ក. សរសេរ \(F_1\) និង \(F_2\) ជាទម្រង់ \(a+bi\)។ ខ. គណនាកម្លាំងសរុប។ គ. ត្រូវការកម្លាំងទី ៣ \(F_3\) ដើម្បីឱ្យចំណុចនោះស្ថិតក្នុងលំនឹង (កម្លាំងសរុបស្មើសូន្យ)។ រក \(F_3\) ហើយពន្យល់ទំនាក់ទំនងរវាង \(F_3\) និងកម្លាំងសរុបនៃ \(F_1,\ F_2\)។', 'g12sc-717124b836.svg', '[]', 0, NULL, 5, 'writing', 'អានតាមរូប ៖ \(F_1=3+4i\) និង \(F_2=-1+2i\) kN (1 ពិន្ទុ)
កម្លាំងសរុប ៖ \(F_1+F_2=(3-1)+(4+2)i=2+6i\) kN (1 ពិន្ទុ)
លក្ខខណ្ឌលំនឹង ៖ \(F_1+F_2+F_3=0\) (1 ពិន្ទុ)
ដូច្នេះ \(F_3=-(F_1+F_2)=-2-6i\) kN (1 ពិន្ទុ)
ទំនាក់ទំនង ៖ \(F_3\) ជាចំនួនផ្ទុយនៃកម្លាំងសរុប មានវ៉ិចទ័ររូបភាពស្មើប៉ុន្តែទិសផ្ទុយ (ឆ្លុះតាមគល់ \(O\)) (1 ពិន្ទុ)', 'ប្លង់កុំផ្លិច', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
