INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20148, 'ទន្លេមួយហូរតាមអ័ក្សពិតក្នុងប្លង់កុំផ្លិច (១ ឯកតា = ១ km)។ ភូមិ \(A\) និង \(B\) មានទីតាំង \(1+3i\) និង \(5+2i\) នៅម្ខាងដូចគ្នានៃទន្លេដូចរូប។ ត្រូវសង់ស្ថានីយ៍បូមទឹក \(P\) នៅលើច្រាំងទន្លេ ដើម្បីឱ្យប្រវែងបំពង់ទឹក \(AP+PB\) ខ្លីបំផុត។ ក. ពន្យល់ថា \(B\) ត្រូវជំនួសដោយចំណុចឆ្លុះ \(B''\) ហើយរក \(B''\)។ ខ. រកទីតាំង \(P\)។', 'g12sc-444c37fa3a.svg', '[]', 0, NULL, 5, 'writing', 'ចំណុចឆ្លុះ \(B''\) នៃ \(B\) តាមទន្លេ (អ័ក្សពិត) គឺចំនួនឆ្លាស់ \(\overline{5+2i}=5-2i\) ពោលគឺ \(B''(5,\ -2)\) (1 ពិន្ទុ)
ដោយ \(PB=PB''\) (ស្ថិតលើអ័ក្សឆ្លុះ) នោះ \(AP+PB=AP+PB''\) (1 ពិន្ទុ)
\(AP+PB''\) ខ្លីបំផុតពេល \(A,\ P,\ B''\) ត្រង់គ្នា (វិសមភាពត្រីកោណ) ដូច្នេះ \(P\) ជាចំណុចប្រសព្វនៃ \(AB''\) នឹងអ័ក្សពិត (1 ពិន្ទុ)
បន្ទាត់ \(AB''\) ៖ ជម្រាល \(\dfrac{-2-3}{5-1}=-\dfrac54\) សមីការ \(y-3=-\dfrac54(x-1)\) (1 ពិន្ទុ)
ដាក់ \(y=0\) ៖ \(x=1+\dfrac{12}{5}=\dfrac{17}{5}\) ដូច្នេះ \(P=\dfrac{17}{5}=3{,}4+0i\) (ស្ថិតត្រង់ \(3{,}4\ \text{km}\) ពីគល់) (1 ពិន្ទុ)', 'ប្លង់កុំផ្លិច', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Create');
