INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20149, 'ដីស្រែរាងប្រលេឡូក្រាម \(ABCD\) មានកំពូលតាមលំដាប់ \(A,\ B,\ C,\ D\)។ កំពូលបីស្គាល់ទីតាំងតាមចំនួនកុំផ្លិច \(A=1+i\), \(B=4+2i\), \(C=5+5i\) (១ ឯកតា = ១០ m) ដូចរូប។ ក. រកទីតាំងកំពូល \(D\)។ ខ. ផ្ទៀងផ្ទាត់ថាអង្កត់ទ្រូង \(AC\) និង \(BD\) មានចំណុចកណ្ដាលតែមួយ។', 'g12sc-8f34fbde56.svg', '[]', 0, NULL, 5, 'writing', 'ប្រលេឡូក្រាម \(ABCD\) មាន \(\overrightarrow{AB}=\overrightarrow{DC}\) គឺ \(B-A=C-D\) (1 ពិន្ទុ)
ដូច្នេះ \(D=A+C-B\) (1 ពិន្ទុ)
គណនា ៖ \(D=(1+i)+(5+5i)-(4+2i)=2+4i\) ពោលគឺ \(D(2,\ 4)\) (1 ពិន្ទុ)
ចំណុចកណ្ដាលនៃ \(AC\) ៖ \(\dfrac{(1+i)+(5+5i)}{2}=3+3i\) (1 ពិន្ទុ)
ចំណុចកណ្ដាលនៃ \(BD\) ៖ \(\dfrac{(4+2i)+(2+4i)}{2}=3+3i\) ដូចគ្នា ដូច្នេះប្រលេឡូក្រាមត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ប្លង់កុំផ្លិច', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20150, 'ក្នុងសៀគ្វីតម្រង (filter) មួយ ការឆ្លើយតបនៃសៀគ្វីត្រូវបានតាងដោយចំនួនកុំផ្លិច \(H=\dfrac{1}{1+i\omega RC}\) ដែល \(\omega\) ជាប្រេកង់មុំ ហើយ \(R\) និង \(C\) ជាភាពធន់ និងចំណុះ។ ចំពោះតម្លៃដែល \(\omega RC=2\) ។ ក. សរសេរ \(H\) ជាទម្រង់ \(a+bi\)។ ខ. បញ្ជាក់ផ្នែកពិត និងផ្នែកនិមិត្តនៃ \(H\)។ គ. ផ្ទៀងផ្ទាត់ថា \(H\cdot(1+2i)=1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស ៖ \(H=\dfrac{1}{1+2i}\) (1 ពិន្ទុ)
គុណភាគយក និងភាគបែងនឹង \(1-2i\) ៖ \(H=\dfrac{1-2i}{(1+2i)(1-2i)}\) (1 ពិន្ទុ)
ភាគបែង ៖ \(1^2-(2i)^2=1+4=5\) (1 ពិន្ទុ)
ទម្រង់ពីជគណិត ៖ \(H=\dfrac{1-2i}{5}=\dfrac15-\dfrac25i\) ផ្នែកពិត \(0{,}2\) ផ្នែកនិមិត្ត \(-0{,}4\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(\left(\dfrac15-\dfrac25i\right)(1+2i)=\dfrac{1+2i-2i-4i^2}{5}=\dfrac55=1\) ត្រឹមត្រូវ។ (1 ពិន្ទុ)', 'ប្រមាណវិធីលើចំនួនកុំផ្លិច', 'pisa', 0, '12SC', 'ចំនួនកុំផ្លិចទម្រង់ពីជគណិត', 'ជំពូកទី 1 : ចំនួនកុំផ្លិច', NULL, 0, 'Apply');
